mapper.select:
SELECT al.id, al.user_id AS userId, al.facility_id AS facilityId, al.access_request_id AS accessRequestId, al.result, al.decision_reason AS decisionReason, al.accessed_at AS accessedAt FROM access_logs al
JOIN users u ON al.user_id = u.id
JOIN facilities f ON al.facility_id = f.id
AND u.name LIKE CONCAT('%', #{userName}, '%')
AND f.name LIKE CONCAT('%', #{facilityName}, '%')
AND al.result = #{result}
AND al.accessed_at >= #{from}
AND al.accessed_at <= #{to}
ORDER BY al.accessed_at DESC
